/** ແກນກາງ_ຄ່າ 안의 연결형 ໄບ_ຄ່າ ສະຕຣີມ_ຄ່າ. Ethernet/TCP 패킷 스택이 아닌 루프백 socket ຊັ້ນ_ຄ່າ. */
public final class ສະຕຣີມ_ເຄືອຂ່າຍ {
    static int[] ສະຖານະ_ຄ່າ = new int[16], ຜອດ_ຄ່າ = new int[16], 짝 = new int[16], ລຸ້ນດຽວກັນ_ຜອດ = new int[16], ລໍຖ້າ_ຄ່າ = new int[16], 묶임 = new int[16];
    static int[] ດ້ານຫນ້າ_ຄ່າ = new int[16], 수 = new int[16], ຂໍ້ມູນ = new int[16 * 1024];
    static int ຕໍ່ໄປ_ລາຍການ = 50000;
    static int 확인(int 열린파일번호) { return 열린파일번호 >= 40 && 열린파일번호 < 56 && ສະຖານະ_ຄ່າ[열린파일번호 - 40] != 0 ? 열린파일번호 - 40 : -1; }
    static boolean 사용중(int ຫມາຍເລກພອດ) { for (int ຫ່ວງ_ດັດຊະນີ = 0; ຫ່ວງ_ດັດຊະນີ < 16; ຫ່ວງ_ດັດຊະນີ++) if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 0 && 묶임[ຫ່ວງ_ດັດຊະນີ] != 0 && ຜອດ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] == ຫມາຍເລກພອດ) return true; return false; }
    public static int ສ້າງ_ເຂົ້າໃນ() {
        for (int ຫ່ວງ_ດັດຊະນີ = 0; ຫ່ວງ_ດັດຊະນີ < 16; ຫ່ວງ_ດັດຊະນີ++) if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] == 0) { ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 1; ລຸ້ນດຽວກັນ_ຜອດ[ຫ່ວງ_ດັດຊະນີ] = ຜອດ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = ດ້ານຫນ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 수[ຫ່ວງ_ດັດຊະນີ] = ລໍຖ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 묶임[ຫ່ວງ_ດັດຊະນີ] = 0; 짝[ຫ່ວງ_ດັດຊະນີ] = -1; return ຫ່ວງ_ດັດຊະນີ + 40; }
        return -24;
    }
    public static int 묶기(int 열린파일번호, int 통신주소, int ຫມາຍເລກພອດ) {
        int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9;
        if (통신주소 != 0 && 통신주소 != 0x7f000001) return -99;
        if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 1 || ຫມາຍເລກພອດ < 0 || ຫມາຍເລກພອດ > 65535) return -22;
        if (ຫມາຍເລກພອດ == 0) { do { ຫມາຍເລກພອດ = ຕໍ່ໄປ_ລາຍການ++; if (ຕໍ່ໄປ_ລາຍການ > 65535) ຕໍ່ໄປ_ລາຍການ = 50000; } while (사용중(ຫມາຍເລກພອດ)); }
        if (사용중(ຫມາຍເລກພອດ)) return -98; ຜອດ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = ຫມາຍເລກພອດ; 묶임[ຫ່ວງ_ດັດຊະນີ] = 1; ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 2; return 0;
    }
    public static int 듣기(int 열린파일번호, int 연결대기한도) { int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9; if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 2 || 연결대기한도 < 1) return -22; ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 3; return 0; }
    public static int ເຊື່ອມຕໍ່(int 열린파일번호, int 통신주소, int ຫມາຍເລກພອດ) {
        int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9; if (통신주소 != 0x7f000001) return -101;
        if (ຫມາຍເລກພອດ < 1 || ຫມາຍເລກພອດ > 65535 || ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] > 2) return -22;
        int 수신쪽 = -1; for (int ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ = 0; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ < 16; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ++) if (ສະຖານະ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] == 3 && ຜອດ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] == ຫມາຍເລກພອດ) 수신쪽 = ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ;
        if (수신쪽 < 0) return -111;
        int 대기여부 = 0; for (int ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ = 0; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ < 16; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ++) if (ລໍຖ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] == 수신쪽 + 1) 대기여부++;
        if (대기여부 >= 4) return -11;
        if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] == 1) { int 처리값 = 묶기(열린파일번호, 0x7f000001, 0); if (처리값 < 0) return 처리값; }
        int 다른번호 = ສ້າງ_ເຂົ້າໃນ(); if (다른번호 < 0) return 다른번호; 다른번호 -= 40;
        ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = ສະຖານະ_ຄ່າ[다른번호] = 4; 짝[ຫ່ວງ_ດັດຊະນີ] = 다른번호; 짝[다른번호] = ຫ່ວງ_ດັດຊະນີ; ຜອດ_ຄ່າ[다른번호] = ຫມາຍເລກພອດ; ລຸ້ນດຽວກັນ_ຜອດ[ຫ່ວງ_ດັດຊະນີ] = ຫມາຍເລກພອດ; ລຸ້ນດຽວກັນ_ຜອດ[다른번호] = ຜອດ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ]; ລໍຖ້າ_ຄ່າ[다른번호] = 수신쪽 + 1; return 0;
    }
    public static int ຕອບຮັບ_ການເຊື່ອມຕໍ່(int 열린파일번호) { int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9; if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 3) return -22; for (int ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ = 0; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ < 16; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ++) if (ສະຖານະ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] != 0 && ລໍຖ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] == ຫ່ວງ_ດັດຊະນີ + 1) { ລໍຖ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] = 0; return ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ + 40; } return -11; }
    public static int ຂຽນ(int 열린파일번호, int 항목수) {
        int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9; if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 4) return -107;
        if (항목수 < 0 || 항목수 > 512) return -22; if (항목수 == 0) return 0;
        int ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ = 짝[ຫ່ວງ_ດັດຊະນີ]; if (ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ < 0) return -32; int 총수 = 1024 - 수[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ]; if (총수 == 0) return -11; if (총수 > 항목수) 총수 = 항목수;
        for (int ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ = 0; ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ < 총수; ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ++) ຂໍ້ມູນ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ * 1024 + (ດ້ານຫນ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] + 수[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] + ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ) % 1024] = 되돌림망.ສົ່ງຕໍ່_ຄ່າ[ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ]; 수[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] += 총수; return 총수;
    }
    public static int 읽기(int 열린파일번호, int 항목수) {
        int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9; if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] != 4) return -107; if (항목수 < 0 || 항목수 > 512) return -22;
        if (항목수 == 0) return 0; if (수[ຫ່ວງ_ດັດຊະນີ] == 0) return 짝[ຫ່ວງ_ດັດຊະນີ] < 0 ? 0 : -11; if (항목수 > 수[ຫ່ວງ_ດັດຊະນີ]) 항목수 = 수[ຫ່ວງ_ດັດຊະນີ];
        for (int ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ = 0; ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ < 항목수; ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ++) 되돌림망.ສົ່ງຕໍ່_ຄ່າ[ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ] = ຂໍ້ມູນ[ຫ່ວງ_ດັດຊະນີ * 1024 + (ດ້ານຫນ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] + ການປຽບທຽບ_ຈັດຕໍາແຫນ່ງ) % 1024]; ດ້ານຫນ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = (ດ້ານຫນ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] + 항목수) % 1024; 수[ຫ່ວງ_ດັດຊະນີ] -= 항목수; return 항목수;
    }
    public static int 창구읽기(int 열린파일번호) { int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); return ຫ່ວງ_ດັດຊະນີ < 0 ? -9 : ຜອດ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ]; }
    public static int 상대창구읽기(int 열린파일번호) { int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); return ຫ່ວງ_ດັດຊະນີ < 0 ? -9 : ລຸ້ນດຽວກັນ_ຜອດ[ຫ່ວງ_ດັດຊະນີ]; }
    public static int ປິດ(int 열린파일번호) {
        int ຫ່ວງ_ດັດຊະນີ = 확인(열린파일번호); if (ຫ່ວງ_ດັດຊະນີ < 0) return -9;
        if (ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] == 3) for (int ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ = 0; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ < 16; ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ++) if (ລໍຖ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] == ຫ່ວງ_ດັດຊະນີ + 1) { if (짝[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] >= 0) 짝[짝[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ]] = -1; ສະຖານະ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] = ລໍຖ້າ_ຄ່າ[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] = 묶임[ການຮວມພາຍໃນ_ຈັດຕໍາແຫນ່ງ] = 0; }
        if (짝[ຫ່ວງ_ດັດຊະນີ] >= 0) 짝[짝[ຫ່ວງ_ດັດຊະນີ]] = -1; ສະຖານະ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 묶임[ຫ່ວງ_ດັດຊະນີ] = 수[ຫ່ວງ_ດັດຊະນີ] = ລໍຖ້າ_ຄ່າ[ຫ່ວງ_ດັດຊະນີ] = 0; return 0;
    }
}
